emit-metric.value:
@{
            var body = context.Response.Body?.As<JObject>(preserveContent: true);
            var pages = body?["analyzeResult"]?["pages"] as JArray;
            return pages != null ? (double)pages.Count : 0.0;
        }

dimension.value:
@{
            var parameters = context.Request.MatchedParameters;
            return parameters.ContainsKey("modelId") ? parameters["modelId"] : "";
        }
